// WF6 · Normalizar mensaje (Code, una vez para todos los ítems)
// La costura de WF6 (13.13.3). Venga de donde venga el mensaje (hoy
// getUpdates; con un servidor, un Telegram Trigger), sale siempre con la
// misma forma: { update_id, chat_id, chat_tipo, fecha, texto }.
// Todo lo que está después no sabe cómo llegó.

// Validación positiva: sin la confirmación no se procesa nada. Los mensajes
// siguen en Telegram y llegan otra vez en la próxima vuelta.
const confirmacion = $('Confirmar lectura').first().json;
if (confirmacion.ok !== true) {
  throw new Error('Telegram no confirmó la lectura; no proceso nada: ' +
    JSON.stringify(confirmacion).slice(0, 200));
}

const updates = $('Pedir mensajes').first().json.result;
const salida = [];
for (const u of updates) {
  const m = u.message;
  if (!m || !m.chat) continue;          // solo mensajes (allowed_updates)
  salida.push({ json: {
    update_id: u.update_id,
    chat_id:   m.chat.id,
    chat_tipo: m.chat.type,
    fecha:     m.date,                   // segundos Unix, puesto por Telegram
    texto:     typeof m.text === 'string' ? m.text : '',
  }});
}
return salida;

// WF6 · Filtrar (Code, una vez para todos los ítems)
// Regla 1 (13.13.2): solo el chat privado del autor. Cualquier otro chat se
// ignora SIN responder (no le confirma a nadie que el bot existe).
// Regla 2: un mensaje de más de 10 minutos no se ejecuta; se marca como
// tarde y más adelante se le contesta que llegó tarde.
// Si no queda ningún mensaje, el flujo termina acá (cero ítems, a propósito).

const CHAT_AUTOR = 5593622386;
const TOPE_ATRASO_MIN = 10;
const ahora = Date.now();

const salida = [];
for (const item of $input.all()) {
  const m = item.json;
  if (m.chat_id !== CHAT_AUTOR || m.chat_tipo !== 'private') continue;
  const atraso_min = Math.floor((ahora - m.fecha * 1000) / 60000);
  salida.push({ json: { ...m, atraso_min, tarde: atraso_min > TOPE_ATRASO_MIN } });
}
return salida;

// WF6 · Interpretar comando (Code, una vez para todos los ítems)
// Saca de cada texto: el comando, la duración (solo /pausar) y el nombre del
// cultivo (opcional; hace falta solo con varios cultivos activos).
//   /estado            /estado Tomate
//   /pausar            (2 h)      /pausar 3h   /pausar 30m   /pausar 3 h Tomate
//   /reanudar          /diagnostico          /ayuda   /start
// Tolera el sufijo @nombre_del_bot (/estado@experto_agro_tesis_bot), las
// mayúsculas y las tildes (/diagnóstico).
// Una duración inválida (/pausar 0h, /pausar 30h, /pausar 3) no llega a la
// base: se contesta con el formato correcto. El tope lo vuelve a controlar
// fn_pausar_cultivo, que es la que decide.

const PAUSA_DEFECTO_MIN = 120;
const TOPE_MIN = 1440;
const COMANDOS = ['estado', 'diagnostico', 'pausar', 'reanudar', 'ayuda', 'start'];

const sinTildes = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '');

// "3h" -> 180, "30m" -> 30, "90min" -> 90. Cualquier otra cosa -> null.
function aMinutos(tok) {
  const m = /^(\d{1,5})(h|hs|hora|horas|m|min|mins|minuto|minutos)$/i.exec(tok);
  if (!m) return null;
  const n = Number(m[1]);
  return m[2].toLowerCase().startsWith('h') ? n * 60 : n;
}

return $input.all().map(item => {
  const m = item.json;
  const texto = m.texto.trim();
  const out = { ...m, comando: 'no_entendido', minutos: null, nombre: '', error_formato: '' };
  if (!texto.startsWith('/')) return { json: out };

  const [primero, ...resto] = texto.split(/\s+/);
  const cmd = sinTildes(primero.slice(1).split('@')[0].toLowerCase());
  if (!COMANDOS.includes(cmd)) return { json: out };
  out.comando = cmd === 'start' ? 'ayuda' : cmd;

  let args = resto;
  if (cmd === 'pausar') {
    if (args.length > 0 && /^\d/.test(args[0])) {
      // Empieza con un número: es la duración. Acepta "3h" y "3 h".
      let tok = args[0], usados = 1;
      if (/^\d+$/.test(tok) && args[1] && /^[a-z]+$/i.test(args[1])) { tok += args[1]; usados = 2; }
      const min = aMinutos(tok);
      if (min === null) {
        out.error_formato = `No entendí la duración «${tok}». Usá /pausar 3h o /pausar 30m. Sin duración, pausa 2 h.`;
      } else if (min < 1 || min > TOPE_MIN) {
        out.error_formato = `La pausa tiene que ser de 1 minuto a 24 h, y «${tok}» queda afuera. ` +
          'Si hace falta más, volvé a pausar cuando termine.';
      } else {
        out.minutos = min;
      }
      args = args.slice(usados);
    } else {
      out.minutos = PAUSA_DEFECTO_MIN;
    }
  }
  out.nombre = args.join(' ');
  return { json: out };
});

// WF6 · Elegir cultivo (Code, una vez para todos los ítems)
// Para cada mensaje decide qué hacer y deja listo lo que hace falta:
//   accion 'responder'  → texto listo (ayuda, estado, llegó tarde, errores)
//   accion 'pausa'      → cultivo_id y minutos (0 = reanudar) para la RPC
//   accion 'diagnostico'→ pedido para WF2 (sin la foto) y el texto "Analizando"
// Regla 5 (13.13.2): con un solo cultivo activo se usa ese; con varios, el
// comando tiene que traer el nombre. Lee la base UNA vez (Leer estado) para
// todos los mensajes de la corrida.
// Todas las salidas tienen los mismos campos: chat_id, accion, texto,
// cultivo_id, minutos, nombre_cultivo, pedido.

const ZONA = 'America/Argentina/Buenos_Aires';
const UN_DIA_MS = 24 * 60 * 60 * 1000;

// ---- Lo que devolvió la base ----------------------------------------------
// Validación positiva: un cultivo es una fila con cultivo_id. Un error del
// nodo (continúa con el error como dato) o la respuesta vacía no lo son.
const filas = $('Leer estado').all().map(i => i.json);
const cultivos = filas.filter(f => typeof f.cultivo_id === 'string');
const errorBase = cultivos.length === 0 && filas.some(f => f.error !== undefined);

// ---- Formatos ---------------------------------------------------------------
// Hora de Argentina con Intl (JavaScript estándar), sin depender de Luxon.
// El cero de adelante se pone a mano: con 'es-AR', '2-digit' da "4/11".
const FORMATO = new Intl.DateTimeFormat('en-US', { timeZone: ZONA, day: 'numeric', month: 'numeric',
  hour: 'numeric', minute: 'numeric', hourCycle: 'h23' });
const ms = iso => Date.parse(iso);
const dos = s => String(Number(s)).padStart(2, '0');
function fecha(iso) {
  const p = Object.fromEntries(FORMATO.formatToParts(new Date(ms(iso))).map(x => [x.type, x.value]));
  return `${dos(p.day)}/${dos(p.month)} ${dos(p.hour)}:${dos(p.minute)}`;
}
const uno = x => String(Math.round(x * 10) / 10);
const ph = x => Number(x).toFixed(1);
const dato = (x, f) => (x === null || x === undefined) ? 'sin dato' : f(x);

function hace(iso) {
  const min = Math.floor((Date.now() - ms(iso)) / 60000);
  if (min < 1) return 'recién';
  if (min < 60) return `hace ${min} min`;
  const h = Math.floor(min / 60);
  if (h < 24) return `hace ${h} h`;
  const d = Math.floor(h / 24);
  return d === 1 ? 'hace 1 día' : `hace ${d} días`;
}

function atraso(min) {
  if (min < 60) return `${min} min`;
  const h = Math.floor(min / 60);
  return h < 48 ? `${h} h` : `${Math.floor(h / 24)} días`;
}

// ✅ dentro del rango de la etapa, ⚠️ afuera. Sin dato o sin rango, sin marca.
function marca(x, min, max) {
  if (x === null || x === undefined || min === null || max === null) return '';
  return (x >= min && x <= max) ? ' ✅' : ' ⚠️';
}

const RESULTADO_RIEGO = {
  exitoso:       'funcionó (la humedad volvió al rango)',
  insuficiente:  'subió la humedad, pero no alcanzó',
  fallo_sistema: 'no tuvo efecto (la humedad no subió)',
  pendiente:     'esperando el control',
  sin_control:   'sin control (no llegó una lectura a tiempo)'
};
const ORDEN_RIEGO = {
  pendiente: ' · la placa no tomó la orden',
  entregado: ' · la placa no confirmó',
  error:     ' · la placa avisó un error',
};

const enPausa = c => c.mantenimiento_hasta !== null && c.mantenimiento_hasta !== undefined
  && ms(c.mantenimiento_hasta) > Date.now();

// ---- Textos -----------------------------------------------------------------
const AYUDA = [
  '🤖 Comandos',
  '/estado: cómo está el cultivo ahora',
  '/diagnostico: la IA analiza la última foto',
  '/pausar: pausa el riego y los avisos 2 h (o /pausar 3h, /pausar 30m; hasta 24 h)',
  '/reanudar: termina la pausa',
  '/ayuda: esta lista',
  '',
  'Con más de un cultivo activo, agregá el nombre: /estado Tomate',
].join('\n');

function textoEstado(c) {
  const l = [];
  l.push(`🌱 ${c.nombre}`);
  const dias = c.dias_en_etapa === null ? '' : `, día ${c.dias_en_etapa}`;
  const est = c.duracion_estimada_dias === null ? '' : ` (se estiman ${c.duracion_estimada_dias})`;
  l.push(`Etapa: ${c.etapa ?? 'sin etapa'}${dias}${est}`);
  l.push('');
  if (c.ultima_lectura_fecha === null) {
    l.push('Última lectura: ninguna todavía');
  } else {
    const vieja = Date.now() - ms(c.ultima_lectura_fecha) > UN_DIA_MS ? ' ⚠️' : '';
    l.push(`Última lectura: ${fecha(c.ultima_lectura_fecha)} (${hace(c.ultima_lectura_fecha)})${vieja}`);
    l.push(`💧 Humedad ${dato(c.humedad, x => uno(x) + ' %')} (rango ${uno(c.humedad_min)} a ${uno(c.humedad_max)})` +
           marca(c.humedad, c.humedad_min, c.humedad_max));
    l.push(`🧪 pH ${dato(c.ph, ph)} (rango ${ph(c.ph_min)} a ${ph(c.ph_max)})` + marca(c.ph, c.ph_min, c.ph_max));
    l.push(`N ${dato(c.n, uno)} · P ${dato(c.p, uno)} · K ${dato(c.k, uno)} mg/kg ` +
           `(ideal ${uno(c.ideal_n)} · ${uno(c.ideal_p)} · ${uno(c.ideal_k)})`);
    l.push(`🌡️ ${dato(c.temperatura, x => uno(x) + ' °C')} · CE ${dato(c.conductividad, x => uno(x) + ' mS/cm')}`);
  }
  l.push('');
  l.push(`Riego automático: ${c.riego_automatico_disponible === true ? 'disponible' : 'no disponible'}`);
  if (c.riego_fecha === null) {
    l.push('Último riego: ninguno');
  } else {
    const res = RESULTADO_RIEGO[c.riego_resultado] ?? (c.riego_resultado ?? 'sin resultado');
    l.push(`Último riego: ${fecha(c.riego_fecha)}, ${res}${ORDEN_RIEGO[c.riego_comando_estado] ?? ''}`);
  }
  l.push(enPausa(c) ? `⏸️ Pausa: hasta ${fecha(c.mantenimiento_hasta)} (/reanudar para terminar)` : 'Pausa: no');
  l.push(`Última foto: ${c.ultima_foto_fecha === null ? (c.ultima_foto_path ? 'sin fecha' : 'ninguna') : fecha(c.ultima_foto_fecha)}`);
  l.push(`Último diagnóstico: ${c.ultimo_diagnostico_fecha === null ? 'ninguno' : fecha(c.ultimo_diagnostico_fecha)}`);
  return l.join('\n');
}

// ---- /diagnostico ------------------------------------------------------------
// Uno cada 10 min por cultivo, por el cupo gratis de Gemini. Se mide con el
// último registro de WF2: si WF2 falla no deja registro y se puede repetir.
const ESPERA_DIAG_MIN = 10;
const hora = iso => fecha(iso).slice(6);
// WF2 tarda hasta ~90 s en guardar, y mientras tanto la base no ve el pedido.
// La memoria del workflow lo frena unos minutos; si WF2 falló, se puede repetir.
const EN_CAMINO_MIN = 3;
const memoria = $getWorkflowStaticData('global');
memoria.diagPedido = memoria.diagPedido || {};

function diagnostico(c) {
  if (!c.ultima_foto_path) return { texto: `📷 ${c.nombre} no tiene ninguna foto para analizar.` };
  // La vista no encontró el archivo en Storage: bajarlo fallaría.
  if (c.ultima_foto_fecha === null) return { texto: `⚠️ No encontré en Storage la última foto de ${c.nombre}: no la puedo analizar.` };
  if (c.ultimo_diagnostico_fecha !== null) {
    const min = Math.floor((Date.now() - ms(c.ultimo_diagnostico_fecha)) / 60000);
    if (min < ESPERA_DIAG_MIN) {
      const desde = new Date(ms(c.ultimo_diagnostico_fecha) + ESPERA_DIAG_MIN * 60000).toISOString();
      return { texto: `⏳ El último diagnóstico es de hace ${min} min. Hay uno cada ${ESPERA_DIAG_MIN} minutos para cuidar el cupo de la IA: probá desde las ${hora(desde)}.` };
    }
  }
  const pedidoHace = Math.floor((Date.now() - (memoria.diagPedido[c.cultivo_id] ?? 0)) / 60000);
  if (pedidoHace < EN_CAMINO_MIN) {
    return { texto: `⏳ Ya hay un diagnóstico en camino (lo pedí hace ${pedidoHace} min). Si en ${EN_CAMINO_MIN} minutos no llegó, pedilo de nuevo.` };
  }
  memoria.diagPedido[c.cultivo_id] = Date.now();

  const dias = Math.floor((Date.now() - ms(c.ultima_foto_fecha)) / UN_DIA_MS);
  const edad = dias < 1 ? '' : ` (tiene ${dias} ${dias === 1 ? 'día' : 'días'})`;
  const lectura = c.ultima_lectura_fecha === null ? 'no hay lecturas: van sin dato'
    : `los valores, de la última lectura (${fecha(c.ultima_lectura_fecha)})`;
  return {
    accion: 'diagnostico',
    texto: `🔎 Analizando la foto del ${fecha(c.ultima_foto_fecha)}${edad}. En un minuto llega el diagnóstico.`,
    // Los mismos campos que WF1 le manda a WF2 (13.13.3).
    pedido: {
      cultivo_id: c.cultivo_id, etapas_especie_id: c.etapas_especie_id, planta: c.planta, etapa: c.etapa,
      mac_address: c.dispositivo_mac, humedad: c.humedad, ph: c.ph, n: c.n, p: c.p, k: c.k,
      umbrales: { humedad: { min: c.humedad_min, max: c.humedad_max }, ph: { min: c.ph_min, max: c.ph_max },
                  n_ideal: c.ideal_n, p_ideal: c.ideal_p, k_ideal: c.ideal_k },
      estado: 'CONSULTA A PEDIDO',
      observaciones: [
        'Pedido por el usuario desde Telegram (/diagnostico), no por una alerta.',
        `La foto es del ${fecha(c.ultima_foto_fecha)}; ${lectura}.`,
      ],
      path_foto_evento: c.ultima_foto_path,
      origen: 'consulta',
    },
  };
}

// ---- Elegir el cultivo (regla 5) -------------------------------------------
const norm = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const lista = () => cultivos.map(c => c.nombre).join(', ');

function elegir(m) {
  if (errorBase) return { error: '⚠️ No pude leer el estado en la base. Probá de nuevo en unos minutos.' };
  if (cultivos.length === 0) return { error: 'No hay ningún cultivo activo.' };
  const dur = m.comando === 'pausar' && m.minutos !== 120
    ? ' ' + (m.minutos % 60 === 0 ? `${m.minutos / 60}h` : `${m.minutos}m`) : '';
  const ejemplo = `/${m.comando}${dur}`;
  if (m.nombre === '') {
    if (cultivos.length === 1) return { cultivo: cultivos[0] };
    return { error: `Hay ${cultivos.length} cultivos activos: ${lista()}. Decime cuál, por ejemplo: ${ejemplo} ${cultivos[0].nombre}` };
  }
  const buscado = norm(m.nombre);
  const exactos = cultivos.filter(c => norm(c.nombre) === buscado);
  const parecidos = exactos.length ? exactos : cultivos.filter(c => norm(c.nombre).includes(buscado));
  if (parecidos.length === 1) return { cultivo: parecidos[0] };
  if (parecidos.length > 1) {
    return { error: `«${m.nombre}» coincide con más de un cultivo: ${parecidos.map(c => c.nombre).join(', ')}. Escribí el nombre completo.` };
  }
  const pista = m.comando === 'pausar' ? '\nPara la duración: /pausar 3h o /pausar 30m.' : '';
  return { error: `No encontré un cultivo activo que se llame «${m.nombre}». Activos: ${lista()}.${pista}` };
}

// ---- Cada mensaje -----------------------------------------------------------
return $('Interpretar comando').all().map(item => {
  const m = item.json;
  const out = { chat_id: m.chat_id, accion: 'responder', texto: '', cultivo_id: null, minutos: null, nombre_cultivo: '', pedido: null };

  if (m.tarde) {
    out.texto = `⏰ Tu mensaje «${m.texto.trim()}» llegó con ${atraso(m.atraso_min)} de atraso ` +
      '(n8n estaba apagado o sin conexión). No lo ejecuté para no actuar con datos viejos: si todavía hace falta, mandalo de nuevo.';
    return { json: out };
  }
  if (m.comando === 'ayuda') { out.texto = AYUDA; return { json: out }; }
  if (m.comando === 'no_entendido') {
    const t = m.texto.trim();
    out.texto = (t ? `No entendí «${t.slice(0, 60)}».\n\n` : '') + AYUDA;
    return { json: out };
  }
  if (m.error_formato) { out.texto = m.error_formato; return { json: out }; }

  const e = elegir(m);
  if (e.error) { out.texto = e.error; return { json: out }; }
  const c = e.cultivo;
  out.cultivo_id = c.cultivo_id;
  out.nombre_cultivo = c.nombre;

  if (m.comando === 'estado') {
    out.texto = textoEstado(c);
  } else if (m.comando === 'pausar' || m.comando === 'reanudar') {
    out.accion = 'pausa';
    out.minutos = m.comando === 'reanudar' ? 0 : m.minutos;
  } else if (m.comando === 'diagnostico') {
    Object.assign(out, diagnostico(c));
  }
  return { json: out };
});

// WF6 · Texto de la pausa (Code, una vez por cada ítem)
// Arma la respuesta de /pausar y /reanudar con lo que devolvió
// fn_pausar_cultivo: siempre una fila (valido, mantenimiento_hasta,
// estaba_en_pausa, errores). Validación positiva: si no llegó esa fila
// (error de red o de la base), se contesta que no se pudo.

const ZONA = 'America/Argentina/Buenos_Aires';
// El cero de adelante se pone a mano: con 'es-AR', '2-digit' da "4/11".
const FORMATO = new Intl.DateTimeFormat('en-US', { timeZone: ZONA, day: 'numeric', month: 'numeric',
  year: 'numeric', hour: 'numeric', minute: 'numeric', hourCycle: 'h23' });
const dos = s => String(Number(s)).padStart(2, '0');
const partes = t => {
  const p = Object.fromEntries(FORMATO.formatToParts(new Date(t)).map(x => [x.type, x.value]));
  return { day: dos(p.day), month: dos(p.month), year: p.year, hour: dos(p.hour), minute: dos(p.minute) };
};

const pedido = $('Elegir cultivo').item.json;
const r = $json;
const reanudar = pedido.minutos === 0;
const verbo = reanudar ? 'reanudar' : 'pausar';

let texto;
if (r.valido === true && reanudar) {
  texto = r.estaba_en_pausa === true
    ? `▶️ ${pedido.nombre_cultivo}: listo, vuelvo a regar y avisar desde la próxima lectura.`
    : `${pedido.nombre_cultivo} no estaba en pausa: todo sigue normal.`;
} else if (r.valido === true && typeof r.mantenimiento_hasta === 'string') {
  const h = partes(Date.parse(r.mantenimiento_hasta));
  const hoy = partes(Date.now());
  const mismoDia = h.day === hoy.day && h.month === hoy.month && h.year === hoy.year;
  const cuando = mismoDia
    ? `las ${h.hour}:${h.minute}`
    : `el ${h.day}/${h.month} a las ${h.hour}:${h.minute}`;
  texto = `⏸️ ${pedido.nombre_cultivo}: pausado hasta ${cuando}. ` +
    'Mientras tanto no riego ni aviso; las lecturas se siguen guardando. /reanudar para terminar antes.' +
    (r.estaba_en_pausa === true ? '\n(Ya estaba en pausa: quedó esta nueva hora.)' : '');
} else if (r.valido === false && Array.isArray(r.errores) && r.errores.length > 0) {
  texto = `⚠️ No pude ${verbo}: ${r.errores[0]}`;
} else {
  texto = `⚠️ No pude ${verbo}: la base no respondió bien. Probá de nuevo en unos minutos.`;
}

return { json: { chat_id: pedido.chat_id, texto } };

// WF6 · Armar pedido (Code, una vez por cada ítem)
// Junta el pedido de Elegir cultivo con la foto en base64. Si la descarga
// falló, no se llama a WF2 y se avisa.

const MINIMO_BASE64 = 1000;   // ~750 bytes: menos que eso no es una foto (como WF3)

const p = $('Elegir cultivo').item.json;
let foto = $json.foto_base64;
if (foto && typeof foto === 'object' && 'value' in foto) foto = foto.value;
const listo = typeof foto === 'string' && foto.trim().length >= MINIMO_BASE64;

return { json: {
  listo,
  chat_id: p.chat_id,
  texto: listo ? p.texto : '⚠️ No pude bajar la foto de Storage. Probá de nuevo en unos minutos.',
  cuerpo: listo ? { ...p.pedido, foto_base64: foto.trim() } : null,
} };

// WF6 · Texto del diagnóstico (Code, una vez por cada ítem)
// WF2 contesta "Workflow was started" apenas recibe el pedido; el diagnóstico
// llega después, con su propio mensaje.

const a = $('Armar pedido').item.json;
const recibido = $json.message === 'Workflow was started';

return { json: {
  chat_id: a.chat_id,
  texto: recibido ? a.texto : '⚠️ No pude pedir el diagnóstico: WF2 no respondió. Probá de nuevo en unos minutos.',
} };
